impl Icon {
    /// The same export-name resolution as lib/lucideIconByName.ts, including saved aliases.
    pub fn from_name(name: &str) -> Option<Self> {
        let pascal: String = name
            .split('-')
            .map(|part| {
                let mut chars = part.chars();
                chars.next().map_or_else(String::new, |first| {
                    first.to_uppercase().chain(chars).collect()
                })
            })
            .collect();
        LUCIDE_EXPORTS
            .binary_search_by_key(&pascal.as_str(), |(name, _)| *name)
            .ok()
            .map(|at| LUCIDE_EXPORTS[at].1)
    }

    pub fn asset(self) -> ImageSrc {
        ImageSrc::svg_markup(self.markup())
    }
}

